
import { Server as HttpServer } from 'http';
import { WebSocket } from 'faye-websocket';
import FSWatcher from 'chokidar';

export interface LiveServerType {
    server: HttpServer | null;
    watcher: FSWatcher | null;
    newClientCallback: ((clients: WebSocket[]) => void) | null;
    logLevel: number;
    start: (options, callback?) => HttpServer;
    reload: () => void;
    shutdown: () => void;
}

declare const LiveServer: LiveServerType;
export = LiveServer;
